{
  "path": [
    {
      "step": 1,
      "course_id": "EDX2078",
      "rationale": "Foundational understanding of sustainability thinking and triple-bottom-line approaches is essential for building on the learner's existing knowledge of business and management principles."
    },
    {
      "step": 2,
      "course_id": "EDX3225",
      "rationale": "Practical sustainability action plan to overcome barriers and seize opportunities associated with creating a sustainable business is a natural progression from foundational understanding."
    },
    {
      "step": 3,
      "course_id": "EDX3299",
      "rationale": "Navigating complex sustainability issues with insight from the holistic PROMISE framework is a key skill for effective sustainability action planning."
    },
    {
      "step": 4,
      "course_id": "EDX3401",
      "rationale": "Leveraging supply chain technology, analytics, and innovation to optimize processes is essential for creating resilient and sustainable supply chains."
    },
    {
      "step": 5,
      "course_id": "EDX3436",
      "rationale": "A holistic understanding of the growing business case for sustainability in the fashion industry is crucial for effective supply chain management and sustainable business practices."
    }
  ]
}

